insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Ideologia', '1.1', 'Origem do UPALELE', 'O UPALELE foi criado em 2014, seu criador  c L as H eiro.', 1);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Ideologia', '1.2', 'Tomada de decisão', 'Tendo em vista um objetivo único de evolução continua sem arbitrariedade, os colideres exercem a tomada de decisão por meio de votação (grupo de wattsapp específico), tanto pra promoção de novos colideres, quanto pela decisão de penalidades. O líder não vota, salvo a ocasião que o número de colideres for par. Daí o voto do líder sempre será o último e decisivo.', 2);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Ideologia', '1.3', 'Atualização das regras', 'As regras não são imutáveis, mas de acordo com a evolução do clã, serão analisadas em momento oportuno.', 3);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Ideologia', '1.4', 'Visão e princípios do clã', 'O UPALELE foi criado com uma visão de jogo pra uma forma contínua. Seu modal permite que seus membros possam, dentro de seu conturbado cotidiano, jogar sem cobrança de número de doações, sem cobrança de PUSH, sem cobrança de ter que ir a guerra. Um ambiente principalmente que a justiça sempre será feita e não será de um ponto de vista unilateral. É como um júri popular, os colideres que julgam, independente do cargo hierárquico.', 4);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Ideologia', '1.5', 'Atividade dos membros', 'A obrigação no UPALELE é o membro ser ativo: doações de tropas, guerras, liga, jogos do clã ou raide. Tem que somar de alguma forma.', 5);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Ideologia', '1.6', 'Inatividade temporária', 'Caso o membro necessite ficar inativo por demandas da vida, informar a liderança pra não ser banido.', 6);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Ideologia', '1.7', 'Saída do clã', 'Não é permitida a saída do clã. Obs.: Exceto para participação em campeonato, com prévia autorização da liderança, e Liga de Guerra em outro clã, desde que sejam respeitadas as regras de saída e retorno estabelecidas pela liderança.', 7);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.1', 'Participação em guerra', 'A participação em guerra não é obrigatória.', 8);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.2', 'Heróis ativos', 'É obrigatório 4 heróis ativos.', 9);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.3', 'Doações no mapa', 'As doações no mapa serão feitas pela liderança.', 10);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.4', 'Primeira participação', 'Para a primeira participação de guerra normal ou liga de guerra, é necessário ler as orientações enviadas pelo whatsapp e confirmar a leitura, pois contém a estratégia utilizada.', 11);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.5', 'Seleção para guerras seguintes', 'Após a primeira participação a liderança selecionará o membro se baseando na cor do perfil.', 12);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.6', 'Horário dos ataques', 'Sempre que possível, atacar nas primeiras 12 horas.', 13);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.7', 'Castelo incompleto ou ataques não realizados', 'Quem atacar com castelo incompleto (tropa, feitiço ou cerco) ou não realizar primeiro ou segundo ataque (por a guerra já estar ganha), será punido.', 14);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.8', 'Ataque para bônus', 'Se todas as vilas do mapa já estiverem com as 3 estrelas conquistadas, o ataque para bônus é liberado.', 15);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.9', 'Alvo sendo atacado', 'Se no momento de realizar o ataque, seu alvo estiver sendo atacado por outro membro, deve se esperar o término do ataque para então atacar o alvo, caso não tenham sido conquistadas as 3 estrelas.', 16);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.10', 'Seleção quando o número não fecha', 'Quando o número de membros não for exato pra iniciar a guerra, os membros selecionados pra ficarem de fora, serão os membros que deixarem pra atacar por último ou que apresentarem os piores performace (heróis inativos). Porém, na guerra seguinte retornam ao mapa. Isso não é castigo aos membros, apenas uma forma justa de selecionar os jogadores que tem maior produtividade e hábito de atacar no início da guerra.', 17);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.11', 'Múltiplas contas de novatos', 'Caso o jogador (novato em guerra) tiver mais de uma conta, primeiramente será levada a conta com CV mais forte pra posteriormente participar com as demais contas.', 18);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.12', 'Problemas pessoais extraordinários', 'Quem tiver problemas pessoais extraordinários, deve reportar o quanto antes pelo whatsapp, para realocarmos ataques e o membro não sofrer punição. Quando não for possível a comunicação antecipada, o membro será banido e ele deverá se reportar ao líder ou a um colider no privado para ser avaliado seu retorno.', 19);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.13', 'Estratégia de guerra', 'ESTRATÉGIA:', 20);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.14', 'Primeiro ataque — alvo inicial', 'Primeiro ataque: Atacar dois alvos abaixo de seu espelho (Exemplo: O 2 de nosso mapa, ataca o 4 do mapa inimigo).', 21);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.15', 'Primeiro ataque — alvo com estrela disponível', 'Caso a vila já tenha sido atacada, mas esteja com estrela disponível, deve se ataca la pra tentar adquirir as 3 estrelas.', 22);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.16', 'Primeiro ataque — vila abaixo', 'Caso a vila tenha sido atacada e esteja com 3 estelas conquistadas, deve se atacar a vila abaixo com estrela disponível.', 23);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.17', 'Primeiro ataque — vila acima', 'Se todas as vilas abaixo já estiverem com 3 estrelas conquistadas, o ataque deverá ser feito na vila acima (debaixo pra cima) com estrela disponível.', 24);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.18', 'Segundo ataque — mesmo nível de CV', 'Segundo ataque:  Atacar o oponente com mesmo nível de centro de vila mais abaixo no mapa com estrela disponível.', 25);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.19', 'Segundo ataque — CV inferior', 'Caso não tenha oponentes do mesmo centro de vila disponível, atacar oponente de centro de vila inferior(atacar a vila acima no mapa).', 26);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Guerra de clã', '2.20', 'Segundo ataque — CV superior', 'Caso não tenham disponíveis oponentes do mesmo centro de vila ou inferior, atacar oponente de centro de vila superior, mas sempre de baixo pra cima com estrela disponível.', 27);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.1', 'Participação na Liga de Guerra', 'A Liga de guerra não é obrigatória.', 28);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.2', 'Heróis ativos', 'É obrigatório 4 heróis ativos.', 29);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.3', 'Estratégia do espelho', 'A estratégia é atacar o espelho.', 30);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.4', 'Participação dos membros', 'Todos os membros do clã são levados para que possam ganhar medalhas.', 31);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.4.1', 'Seleção inicial do mapa', 'Os membros que iniciarão no mapa na primeira guerra serão definidos pelo líder, considerando o nível do Centro de Vila /  performance ofensivo anteriores / potencial defensivo.', 32);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.5', 'Requisito de guerra anterior', 'Pra iniciar no mapa de guerra o membro tem que ter participado de pelo menos uma guerra normal anteriormente. Caso não tiver participado anteriormente, entrará na lista de revezamento.', 33);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.6', 'Múltiplas contas', 'Se o jogador (novato em guerra) tiver mais de uma conta, primeiramente será levada a conta com centro de vila mais forte e posteriormente participar com as demais contas.', 34);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.7', 'Revezamento após duas estrelas', 'Caso o jogador consiga 2 estrelas, revezará com os membros da reserva.', 35);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.7.1', 'Substituição durante a liga', 'O líder poderá fazer a substituição que analisar necessária durante a liga.', 36);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.8', 'Alvo atacado equivocadamente', 'Caso seu alvo tenha sido atacado equivocadamente, deve se atacar o espelho de quem atacou seu alvo.', 37);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.9', 'Troca de alvo', 'É permitido trocar de alvo, desde que seja autorizado/combinado pelo chat ou grupo de whatsApp.', 38);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.10', 'Horário de ataque e substituição', 'Sempre que possível, atacar nas primeiras 12 horas, pois a liderança precisa avaliar o performace de cada ataque e selecionar os membros que participarão da Liga no dia seguinte. Nas últimas 2 horas da guerra, a liderança substituirá o membro que não efetuou o ataque. O membro entrará na fila de revezamento.', 39);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.11', 'Medalhas extras por mérito', 'As medalhas extras da liga são dadas aos jogadores que conquistarem mais estrelas (meritocracia).', 40);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.12', 'Medalhas extras em múltiplas contas', 'Membros com mais de um centro de vila, só poderão receber medalhas extras em uma Vila. Porém, fica de livre escolha do membro a conta que receberá as medalhas extras. Mesmo que a conta escolhida não tenha conquistado meritocracia.', 41);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.13', 'Participação em outra liga', 'Membros que não forem selecionados pra participar da liga (15 titulares + 5 reservas), poderão sair para participar da liga em outro clã, sendo nossa sugestão o nosso clã secundário.', 42);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Liga de guerra', '3.14', 'Período de saída e retorno', 'A saída poderá ocorrer entre o dia 29 do mês anterior e o dia 31. O retorno deverá ocorrer entre o dia 8 e o dia 11. Não serão permitidas saídas / retornos fora desses períodos.', 43);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Raide', '4.1', 'Participação na Raide', 'A participação da Raide é obrigatória.', 44);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Raide', '4.2', 'Doação de ouro da Capital', 'As doações de ouro na Capital devem ser feitas nas melhorias que estão marcadas como prioridade ou destinada a Torre do tesouro.', 45);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Raide', '4.3', 'Ordem e estratégia de ataque', 'Não existe ordem de ataque ou estratégia a ser seguida.', 46);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Raide', '4.4', 'Ataques e progressão da liga', 'Atualmente já temos o mapa com todas as melhorias possíveis. Mas pedimos que sempre façam os ataques para que possamos subir de liga e acumular recursos na Torre do tesouro.', 47);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Raide', '4.5', 'Destino do ouro da Capital', 'A doação do ouro da capital deve ser destinada a Torre do Tesouro ou também pode ser doado no clã secundário (somente aos domingos).', 48);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Jogos do clã', '5.1', 'Participação nos Jogos do Clã', 'A participação nos jogos é obrigatória.', 49);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Jogos do clã', '5.2', 'Meta coletiva de pontos', 'A conclusão coletiva dos pontos é fundamental pro clã resgatar todas as recompensas.', 50);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Jogos do clã', '5.3', 'Recompensa extra', 'Quem atingir 4.000 pontos individuais ganha a recompensa extra.', 51);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Push', '6.1', 'Push não obrigatório', 'Em dado momento de evolução do UPALELE, será feito PUSH de forma não obrigatória pra dar mais visibilidade ao UPALELE e também para os membros obterem novas experiências.', 52);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('WhatsApp', '7.1', 'Participação no WhatsApp', 'Não é obrigatória a participação no grupo de whatsapp.', 53);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('WhatsApp', '7.2', 'WhatsApp para eventos de guerra', 'Os membros que quiserem participar de eventos de guerra será obrigatória a participação, por lá passamos a estratégia.', 54);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('WhatsApp', '7.3', 'Identificação pelo apelido', 'Solicitamos que ao ingressar no grupo de whatsapp, seja inserido no campo "apelido" o nick que o jogador usa no jogo. Desta forma todos se identificam.', 55);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('WhatsApp', '7.4', 'Argumentação após banimento', 'No caso de banimento, por ausência de ataque ou qualquer outra infração, o jogador só conseguirá explanar suas argumentações por meio do aplicativo.', 56);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('WhatsApp', '7.5', 'Banimento e avaliação de retorno', 'Pra mantermos o ambiente sadio e com espírito de justiça, banimos a conta. 7.5  O membro banido deve expor sua situação ao líder ou a um Colider pelo whatsapp, pra que possa ser avaliado seu retorno ao clã e cargo pela junta dos colideres.', 57);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Doações', '8.1', 'Regra de doações', 'Não existe regra de doação.', 58);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Doações', '8.3-A', 'Equilíbrio das doações', 'Sempre que possível equilibrar doações, pois esses índices regulados deixa nosso clã com melhor visibilidade pra recrutamento.', 59);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Doações', '8.3-B', 'Equilíbrio das doações', 'Embora não seja cobrado número de doações, esse dado demonstra atividade em jogo.', 60);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Doações', '8.4', 'Saldo de doações e XP', 'O membro não deve se preocupar se está muito negativo, pode estar com zero tropas doadas e 50.000 recebidas, isso é bem visto. O foco é gerar XP ao clã.', 61);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Anciões', '9.1', 'Promoção a ancião', 'A promoção pra se tornar um ancião é feita pelo líder do clã. Essa promoção é reconhecida pela atividade do jogo, seja por número de doações (doadas e recebidas), participação em raide, jogos do clã e demais eventos, mas principalmente na atividade em guerras, pois o foco do clã é guerra. Porém, atendendo um desses critérios o líder pode decidir pela promoção.', 62);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Anciões', '9.2', 'Recrutamento', 'Solicitamos aos anciões que enviem link do clã do global a outros grupos e jogadores (perfil exigido), afim de aumentar a malha de recrutamento (principal função do ancião).', 63);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Anciões', '9.3', 'Aceitação de membros', 'Anciões podem aceitar membros que solicitem a entrada no clã, porém, somente os membros que tiverem Centro de Vila mínimo 17, Rei e Rainha nível 100 e 1000 estrelas de guerra. Quando rejeitar, justificar o porquê da rejeição (qual critério).', 64);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Anciões', '9.4', 'Expulsão por não atender requisitos', 'Anciões podem kikar membros que entrarem no clã e não atenderem aos pré-requisitos mínimos exigidos (Centro de Vila mínimo 17 / Rei e Rainha nível 100 / 1000 estrelas de guerra). Porém, solicitamos que sempre se justifique o motivo do kick (qual critério).', 65);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Anciões', '9.5', 'Orientação a novos membros', 'Solicitamos aos anciões que sempre perguntem ao membro que entrar, se ele pretende ir a guerras e informe que para participar de eventos de guerra é necessário participar do grupo do whatsapp pra repasse da estratégia e em seguida solicite o número de telefone e repasse no grupo de whatsapp pra que a liderança possa adiciona lo, usando o @ dos líderes afim de evidenciar a mensagem.', 66);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Anciões', '9.6', 'Membros antigos que saíram', 'Anciões não devem aceitar membros antigos que saiam do clã.', 67);
insert into memorial_source_import(section, rule_number, title, body, sort_order) values ('Anciões', '9.7', 'Ofensas no chat', 'Anciões podem kikar qualquer membro que fizer xingamentos ou ofensas no chat, porém, informando imediatamente a liderança.', 68);
insert into public.memorial_rules (section, rule_number, title, body, is_published, sort_order)
