-- Clan Hub UPALELE: memorial completo transcrito do arquivo original enviado pelo usuário.
-- Idempotente: atualiza regras existentes, inclui faltantes e remove apenas regras do memorial que não constam no documento oficial.
-- Não altera ganchos ativos, histórico punitivo, perfis nem outras tabelas.
begin;
drop table if exists pg_temp.memorial_source_import;
create temporary table memorial_source_import (section text not null, rule_number text not null, title text not null, body text not null, sort_order integer not null, primary key(section, rule_number));
select section, rule_number, title, body, true, sort_order from memorial_source_import
on conflict (section, rule_number) where rule_number is not null do update set title = excluded.title, body = excluded.body, is_published = true, sort_order = excluded.sort_order, updated_at = now();
delete from public.memorial_rules r where not exists (select 1 from memorial_source_import s where s.section = r.section and s.rule_number = r.rule_number);
commit;
-- Conferência esperada: contagem de regras do memorial corresponde às linhas numeradas do documento (incluindo 2.13 Estratégia e 3.4.1 / 3.7.1).
select section, count(*) as total from public.memorial_rules where is_published = true group by section order by min(sort_order);
select rule_number, title, body from public.memorial_rules where section = 'Guerra de clã' and rule_number between '2.13' and '2.20' order by sort_order;
